import 'package:flutter/widgets.dart';

/// Paints the "widgetation" wordmark from an embedded SVG path. The original
/// asset is a 173×46 viewBox with a single filled subpath; we parse it once
/// and cache the resulting [Path] so subsequent paints are pure scale + draw.
class WidgetationWordmarkPainter extends CustomPainter {
  final Color color;

  const WidgetationWordmarkPainter({required this.color});

  static const double viewBoxWidth = 173;
  static const double viewBoxHeight = 46;

  static Path? _cachedPath;
  static Path get _path => _cachedPath ??= _parseSvgPath(_kWordmarkPath);

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.height / viewBoxHeight < size.width / viewBoxWidth
        ? size.height / viewBoxHeight
        : size.width / viewBoxWidth;
    final drawnW = viewBoxWidth * scale;
    final drawnH = viewBoxHeight * scale;
    canvas.save();
    canvas.translate((size.width - drawnW) / 2, (size.height - drawnH) / 2);
    canvas.scale(scale);
    canvas.drawPath(_path, Paint()..color = color);
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant WidgetationWordmarkPainter old) => old.color != color;
}

final _numberRegex = RegExp(r'-?\d*\.?\d+(?:[eE][+-]?\d+)?');
final _commandRegex = RegExp(r'([MmLlHhVvCcSsQqTtAaZz])([^MmLlHhVvCcSsQqTtAaZz]*)');

Path _parseSvgPath(String d) {
  final path = Path();
  double cx = 0, cy = 0;
  double sx = 0, sy = 0;

  for (final m in _commandRegex.allMatches(d)) {
    final cmd = m.group(1)!;
    final args = _numberRegex
        .allMatches(m.group(2)!)
        .map((n) => double.parse(n.group(0)!))
        .toList();

    switch (cmd) {
      case 'M':
        path.moveTo(args[0], args[1]);
        cx = sx = args[0];
        cy = sy = args[1];
        for (var i = 2; i + 1 < args.length; i += 2) {
          path.lineTo(args[i], args[i + 1]);
          cx = args[i];
          cy = args[i + 1];
        }
        break;
      case 'm':
        path.relativeMoveTo(args[0], args[1]);
        cx += args[0];
        cy += args[1];
        sx = cx;
        sy = cy;
        for (var i = 2; i + 1 < args.length; i += 2) {
          path.relativeLineTo(args[i], args[i + 1]);
          cx += args[i];
          cy += args[i + 1];
        }
        break;
      case 'L':
        for (var i = 0; i + 1 < args.length; i += 2) {
          path.lineTo(args[i], args[i + 1]);
          cx = args[i];
          cy = args[i + 1];
        }
        break;
      case 'l':
        for (var i = 0; i + 1 < args.length; i += 2) {
          path.relativeLineTo(args[i], args[i + 1]);
          cx += args[i];
          cy += args[i + 1];
        }
        break;
      case 'H':
        for (final x in args) {
          path.lineTo(x, cy);
          cx = x;
        }
        break;
      case 'h':
        for (final dx in args) {
          path.relativeLineTo(dx, 0);
          cx += dx;
        }
        break;
      case 'V':
        for (final y in args) {
          path.lineTo(cx, y);
          cy = y;
        }
        break;
      case 'v':
        for (final dy in args) {
          path.relativeLineTo(0, dy);
          cy += dy;
        }
        break;
      case 'C':
        for (var i = 0; i + 5 < args.length; i += 6) {
          path.cubicTo(args[i], args[i + 1], args[i + 2], args[i + 3], args[i + 4], args[i + 5]);
          cx = args[i + 4];
          cy = args[i + 5];
        }
        break;
      case 'c':
        for (var i = 0; i + 5 < args.length; i += 6) {
          path.relativeCubicTo(args[i], args[i + 1], args[i + 2], args[i + 3], args[i + 4], args[i + 5]);
          cx += args[i + 4];
          cy += args[i + 5];
        }
        break;
      case 'Z':
      case 'z':
        path.close();
        cx = sx;
        cy = sy;
        break;
    }
  }
  return path;
}

